@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label fw-semibold">Mode</label>
            <div class="btn-group d-flex" role="group">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    var isActive = ThemeService.Current.Mode == mode;
                    <button type="button"
                            class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                            @onclick="() => SetMode(mode)">
                        @mode
                    </button>
                }
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label fw-semibold" for="accentColor">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" id="accentColor" class="form-control form-control-color"
                       value="@ThemeService.Current.AccentColor"
                       @onchange="OnAccentChanged" />
                <span class="text-muted">@ThemeService.Current.AccentColor</span>
            </div>
        </div>
    </div>
</div>

<div class="mt-4">
    <h5>Preview</h5>
    <p>
        Current theme: <strong>@ThemeService.Current.Mode</strong> —
        Accent: <span style="color: @ThemeService.Current.AccentColor; font-weight: bold;">
            @ThemeService.Current.AccentColor
        </span>
    </p>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private async Task SetMode(ThemeMode mode)
    {
        await ThemeService.SetThemeModeAsync(mode);
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        var color = e.Value?.ToString();
        if (!string.IsNullOrWhiteSpace(color))
        {
            await ThemeService.SetAccentColorAsync(color);
        }
    }
}

